import React from "react";
import { useCalculator } from "./hooks/useCalculator";
import "./App.css";

// ─── Small reusable pieces ────────────────────────────────────────────────────

function LeafIcon() {
  return (
    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <path d="M11 20A7 7 0 0 1 9.8 6.1C15.5 5 17 4.48 19 2c1 2 2 4.18 2 8 0 5.5-4.78 10-10 10z"/>
      <path d="M2 21c0-3 1.85-5.36 5.08-6C9.5 14.52 12 13 13 12"/>
    </svg>
  );
}

function BreakdownBar({ breakdown, total }) {
  const colors = {
    transport: "#8fbc8f",
    electricity: "#d4a853",
    water: "#7bb8d4",
    tailoring: "#c4956a",
  };
  const labels = {
    transport: "Transport",
    electricity: "Electricity",
    water: "Water",
    tailoring: "Tailoring",
  };

  return (
    <div className="breakdown">
      <p className="breakdown-title">Emission Breakdown (per unit)</p>
      <div className="breakdown-bar">
        {Object.entries(breakdown).map(([key, val]) => {
          const pct = total > 0 ? (val / total) * 100 : 0;
          return (
            <div
              key={key}
              className="breakdown-segment"
              style={{ width: `${pct}%`, background: colors[key] }}
              title={`${labels[key]}: ${val.toFixed(4)} kg CO₂e`}
            />
          );
        })}
      </div>
      <div className="breakdown-legend">
        {Object.entries(breakdown).map(([key, val]) => (
          <div key={key} className="legend-item">
            <span className="legend-dot" style={{ background: colors[key] }} />
            <span>{labels[key]}</span>
            <span className="legend-val">{val.toFixed(4)}</span>
          </div>
        ))}
      </div>
    </div>
  );
}

function ResultCard({ result, onReset }) {
  if (result.status === "not_found") {
    return (
      <div className="result-card result-not-found">
        <div className="not-found-icon">⚠</div>
        <h3>Not in lookup yet</h3>
        <p>This product/size combination is not in the current dataset (v2.2). Please contact the data owner to add it.</p>
        <button className="btn-secondary" onClick={onReset}>Try another</button>
      </div>
    );
  }

  const { title, size, quantity, pathway, product_type, dye_type, natural_dye,
          total_kg, avoided_kg, per_unit_kg, breakdown } = result;

  return (
    <div className="result-card">
      <div className="result-header">
        <LeafIcon />
        <span className="pathway-badge pathway-badge--{pathway.toLowerCase()}">
          Pathway {pathway} {pathway === "B" ? "· Closed-loop" : "· Standard"}
        </span>
      </div>

      <h2 className="result-title">{title}</h2>
      <p className="result-meta">{product_type} · Size {size} · {dye_type} · {natural_dye === "Yes" ? "Natural dye" : "Undyed"}</p>

      <div className="result-numbers">
        <div className="number-block number-block--main">
          <span className="number-label">Total CO₂e</span>
          <span className="number-value">{total_kg.toFixed(4)}</span>
          <span className="number-unit">kg CO₂e</span>
          <span className="number-sub">{per_unit_kg.toFixed(4)} per unit × {quantity}</span>
        </div>

        {pathway === "B" && (
          <div className="number-block number-block--avoided">
            <span className="number-label">Avoided CO₂e</span>
            <span className="number-value">{avoided_kg.toFixed(4)}</span>
            <span className="number-unit">kg CO₂e</span>
            <span className="number-sub">Closed-loop benefit — shown separately</span>
          </div>
        )}
      </div>

      <BreakdownBar breakdown={breakdown} total={per_unit_kg} />

      <div className="result-footer">
        <p className="methodology-note">Folkcharm LCA Methodology v2.2 · Transport factor 4.983</p>
        <button className="btn-secondary" onClick={onReset}>Calculate another</button>
      </div>
    </div>
  );
}

// ─── Main App ─────────────────────────────────────────────────────────────────

export default function App() {
  const {
    categories,
    category, setCategory,
    title, setTitle,
    size, setSize,
    quantity, setQuantity,
    titles, sizes,
    result,
    calculate,
    reset,
  } = useCalculator();

  const canCalculate = category && title && size && quantity >= 1;

  return (
    <div className="app">
      {/* Background decoration */}
      <div className="bg-circle bg-circle--1" />
      <div className="bg-circle bg-circle--2" />

      <header className="app-header">
        <div className="logo">
          <LeafIcon />
          <span>Folkcharm</span>
        </div>
        <h1 className="app-title">Carbon Emission Calculator</h1>
        <p className="app-subtitle">Cradle-to-gate CO₂e · Methodology v2.2</p>
      </header>

      <main className="app-main">
        {!result ? (
          <div className="form-card">
            <h2 className="form-heading">Calculate Emissions</h2>

            {/* Category selector */}
            <div className="field">
              <label className="field-label" htmlFor="category">Category</label>
              <div className="select-wrapper">
                <select
                  id="category"
                  className="field-select"
                  value={category}
                  onChange={(e) => setCategory(e.target.value)}
                >
                  <option value="">— Select a category —</option>
                  {categories.map((c) => (
                    <option key={c} value={c}>{c}</option>
                  ))}
                </select>
              </div>
            </div>

            {/* Product selector — now filtered by category */}
            <div className="field">
              <label className="field-label" htmlFor="product">Product</label>
              <div className="select-wrapper">
                <select
                  id="product"
                  className="field-select"
                  value={title}
                  onChange={(e) => setTitle(e.target.value)}
                  disabled={!category}
                >
                  <option value="">— Select a product —</option>
                  {titles.map((t) => (
                    <option key={t} value={t}>{t}</option>
                  ))}
                </select>
              </div>
            </div>

            {/* Size selector */}
            <div className="field">
              <label className="field-label" htmlFor="size">Size</label>
              <div className="select-wrapper">
                <select
                  id="size"
                  className="field-select"
                  value={size}
                  onChange={(e) => setSize(e.target.value)}
                  disabled={!title}
                >
                  <option value="">— Select a size —</option>
                  {sizes.map((s) => (
                    <option key={s} value={s}>{s}</option>
                  ))}
                </select>
              </div>
            </div>

            {/* Quantity */}
            <div className="field">
              <label className="field-label" htmlFor="qty">Quantity</label>
              <input
                id="qty"
                type="number"
                className="field-input"
                min="1"
                value={quantity}
                onChange={(e) => setQuantity(Math.max(1, parseInt(e.target.value) || 1))}
              />
            </div>

            <button
              className="btn-primary"
              onClick={calculate}
              disabled={!canCalculate}
            >
              Calculate
            </button>
          </div>
        ) : (
          <ResultCard result={result} onReset={reset} />
        )}
      </main>

      <footer className="app-footer">
        <p>Internal tool · Folkcharm URD-202 · Not for external distribution</p>
      </footer>
    </div>
  );
}
